/// <summary>
/// Метод создания ордера для Bybit
/// </summary>
public class RMarketMethod_Bybit_CreateOrder extends RMarketMethod implements RMarketMethodInterface_CreateOrder
{
    protected RMarketJson_Bybit_CreateOrder_Request requestContract;
    protected RMarketJson_Bybit_Order responseContract;
    protected str symbol;
    protected str side;
    protected str orderType;
    protected str qty;
    protected str price;
    protected str clientOrderId;

}

Method.Source:
/// <summary> Конструктор класса </summary>
public void new()
{
    super();

    apiClient = new RMarketApiClientBybit();
    apiClient.parmHttpMethod(RMarketAPIHttpMethod::POST);
    apiClient.parmMethodUrl('/v5/order/create');

    requestContract = new RMarketJson_Bybit_CreateOrder_Request();

    // Do this before execute()
    //apiClient.setBaseUrl(URL _baseUrl);
    //apiClient.setApiKey(RMarketApiKey _apiKey)
}

/// <summary> Создать ордер на Bybit </summary> /// <param name="_symbol"> Торговый символ </param> /// <param name="_side"> Направление (BUY/SELL) </param> /// <param name="_orderType"> Тип ордера </param> /// <param name="_qty"> Количество </param> /// <param name="_price"> Цена </param> /// <param name="_clientOrderId"> Клиентский ID ордера </param> /// <returns> Результат создания ордера </returns> public void initParameters( str _symbol, str _side, str _orderType, str _qty, str _price = '', str _clientOrderId = '') { /* https://bybit-exchange.github.io/docs/v5/order/create-order category true string Product type UTA2.0, UTA1.0: linear, inverse, spot, option classic account: linear, inverse, spot
symbol true string Symbol name, like BTCUSDT, uppercase only isLeverage false integer Whether to borrow. Unified account Spot trading only. 0(default): false, spot trading 1: true, margin trading, make sure you turn on margin trading, and set the relevant currency as collateral side true string Buy, Sell orderType true string Market, Limit qty true string Order quantity UTA account Spot: Market Buy order by value by default, you can set marketUnit field to choose order by value or qty for market orders Perps, Futures & Option: always order by qty classic account Spot: Market Buy order by value by default Perps, Futures: always order by qty Perps & Futures: if you pass qty="0" and specify reduceOnly=true&closeOnTrigger=true, you can close the position up to maxMktOrderQty or maxOrderQty shown on Get Instruments Info of current symbol marketUnit false string Select the unit for qty when create Spot market orders for UTA account baseCoin: for example, buy BTCUSDT, then "qty" unit is BTC quoteCoin: for example, sell BTCUSDT, then "qty" unit is USDT slippageToleranceType false string Slippage tolerance Type for market order, TickSize, Percent Support linear, inverse, spot trading, but take profit, stoploss, conditional orders are not supported TickSize: the highest price of Buy order = ask1 + slippageTolerance x tickSize; the lowest price of Sell order = bid1 - slippageTolerance x tickSize Percent: the highest price of Buy order = ask1 x (1 + slippageTolerance x 0.01); the lowest price of Sell order = bid1 x (1 - slippageTolerance x 0.01) slippageTolerance false string Slippage tolerance value TickSize: range is [5, 2000], integer only Percent: range is [0.05, 1], up to 2 decimals price false string Order price Market order will ignore this field Please check the min price and price precision from instrument info endpoint If you have position, price needs to be better than liquidation price triggerDirection false integer Conditional order param. Used to identify the expected direction of the conditional order. 1: triggered when market price rises to triggerPrice 2: triggered when market price falls to triggerPrice Valid for linear & inverse orderFilter false string If it is not passed, Order by default. Order tpslOrder: Spot TP/SL order, the assets are occupied even before the order is triggered StopOrder: Spot conditional order, the assets will not be occupied until the price of the underlying asset reaches the trigger price, and the required assets will be occupied after the Conditional order is triggered Valid for spot only triggerPrice false string For Perps & Futures, it is the conditional order trigger price. If you expect the price to rise to trigger your conditional order, make sure: triggerPrice > market price Else, triggerPrice < market price For spot, it is the TP/SL and Conditional order trigger price triggerBy false string Trigger price type, Conditional order param for Perps & Futures. LastPrice IndexPrice MarkPrice Valid for linear & inverse orderIv false string Implied volatility. option only. Pass the real value, e.g for 10%, 0.1 should be passed. orderIv has a higher priority when price is passed as well timeInForce false string Time in force Market order will always use IOC If not passed, GTC is used by default positionIdx false integer Used to identify positions in different position modes. Under hedge-mode, this param is required 0: one-way mode 1: hedge-mode Buy side 2: hedge-mode Sell side orderLinkId false string User customised order ID. A max of 36 characters. Combinations of numbers, letters (upper and lower cases), dashes, and underscores are supported. Futures & Perps: orderLinkId rules: optional param always unique option orderLinkId rules: required param always unique takeProfit false string Take profit price UTA: Spot Limit order supports take profit, stop loss or limit take profit, limit stop loss when creating an order stopLoss false string Stop loss price UTA: Spot Limit order supports take profit, stop loss or limit take profit, limit stop loss when creating an order tpTriggerBy false string The price type to trigger take profit. MarkPrice, IndexPrice, default: LastPrice. Valid for linear & inverse slTriggerBy false string The price type to trigger stop loss. MarkPrice, IndexPrice, default: LastPrice. Valid for linear & inverse reduceOnly false boolean What is a reduce-only order? true means your position can only reduce in size if this order is triggered. You must specify it as true when you are about to close/reduce the position When reduceOnly is true, take profit/stop loss cannot be set Valid for linear, inverse & option closeOnTrigger false boolean What is a close on trigger order? For a closing order. It can only reduce your position, not increase it. If the account has insufficient available balance when the closing order is triggered, then other active orders of similar contracts will be cancelled or reduced. It can be used to ensure your stop loss reduces your position regardless of current available margin. Valid for linear & inverse smpType false string Smp execution type. What is SMP? mmp false boolean Market maker protection. option only. true means set the order as a market maker protection order. What is mmp? tpslMode false string TP/SL mode Full: entire position for TP/SL. Then, tpOrderType or slOrderType must be Market Partial: partial position tp/sl (as there is no size option, so it will create tp/sl orders with the qty you actually fill). Limit TP/SL order are supported. Note: When create limit tp/sl, tpslMode is required and it must be Partial Valid for linear & inverse tpLimitPrice false string The limit order price when take profit price is triggered linear & inverse: only works when tpslMode=Partial and tpOrderType=Limit Spot(UTA): it is required when the order has takeProfit and "tpOrderType"=Limit slLimitPrice false string The limit order price when stop loss price is triggered linear & inverse: only works when tpslMode=Partial and slOrderType=Limit Spot(UTA): it is required when the order has stopLoss and "slOrderType"=Limit tpOrderType false string The order type when take profit is triggered linear & inverse: Market(default), Limit. For tpslMode=Full, it only supports tpOrderType=Market Spot(UTA): Market: when you set "takeProfit", Limit: when you set "takeProfit" and "tpLimitPrice" slOrderType false string The order type when stop loss is triggered linear & inverse: Market(default), Limit. For tpslMode=Full, it only supports slOrderType=Market Spot(UTA): Market: when you set "stopLoss", Limit: when you set "stopLoss" and "slLimitPrice" */ symbol = _symbol; side = _side; orderType = _orderType; qty = _qty; price = _price; clientOrderId = _clientOrderId;
requestContract.parmSymbol(symbol); requestContract.parmSide(side); requestContract.parmOrderType(orderType); requestContract.parmQty(qty);
if (_price) requestContract.parmPrice(price);
if (_clientOrderId) requestContract.parmOrderLinkId(clientOrderId); }

public void prepare()
{
    requestContract.parmCategory("spot");
    //requestContract.parmCategory("linear");
    requestContract.parmIsLeverage(1);
    //requestContract.parmMarketUnit("quoteCoin");

    apiClient.setRequestBody(requestContract.jsonRequest());

    super();
}

public void processResponse()
{
    super();

    str responseStr = apiClient.getResponseBody();

    if (apiClient.getHttpStatus() != System.Net.HttpStatusCode::OK)
        throw Error(strfmt("Request returns error!"));

    responseContract = RMarketJsonSerializer::deserializeObject(
        classNum(RMarketJson_Bybit_Order),
        responseStr) as RMarketJson_Bybit_Order;
}
